        "Ashopping-table1-row2-clo1": "Sembang atau komen kasar atau kesat",
        "Ashopping-table1-row2-clo2": "Minta pembeli membatalkan pesanan lebih daripada 3 kali pada bulan ini",
        "Ashopping-table1-row2-clo3": "Kadar tindak balas pertanyaan Pembeli adalah kurang daripada 80%",
        "Ashopping-table1-row2-clo4": "Sehingga 20 mata",
        "Ashopping-table1-row3": "mungkir janji",
        "Ashopping-table1-row3-clo1": "Penjual gagal memberikan perkhidmatan kepada pembeli seperti yang dijanjikan, memudaratkan hak dan kepentingan pembeli",
        "Ashopping-title3": "3. APAKAH HUKUMAN YANG BERSESUAIAN DENGAN PEMARKAHAN?",
        "Ashopping-table2-tit": "Jika penjual mengumpul sejumlah besar mata, sebahagian daripada faedah jualan penjual akan digantung mengikut jadual di bawah:",
        "Ashopping-table2-header": "Pemarkahan kumulatif",
